Working dir /dayjs. Goal: empirically probe the CURRENT behavior of the timezone plugin. Do NOT edit any repository source files. You may create a temporary jest test file at /dayjs/test/zzz_probe.test.js, run it, and DELETE it afterwards.

Create /dayjs/test/zzz_probe.test.js with this content (adjust only if needed to run):

```js
import MockDate from 'mockdate'
import dayjs from '../src'
import utc from '../src/plugin/utc'
import timezone from '../src/plugin/timezone'

dayjs.extend(utc)
dayjs.extend(timezone)

const NY = 'America/New_York'

it('probe', () => {
  const out = {}
  const newYork = dayjs.tz('2014-06-01 12:00', NY)
  out.newYork_format = newYork.format()
  out.newYork_valueOf = newYork.valueOf()
  out.newYork_offset = newYork.utcOffset()
  out.newYork_formatZ = newYork.format('Z')
  out.newYork_formatZZ = newYork.format('ZZ')
  const ts = newYork.valueOf()
  try { out.tz_ts = dayjs.tz(ts, NY).format() } catch (e) { out.tz_ts = 'ERR ' + e.message }
  try { out.tz_ts_val = dayjs.tz(ts, NY).valueOf() } catch (e) { out.tz_ts_val = 'ERR ' + e.message }
  try { out.tz_date = dayjs.tz(newYork.toDate(), NY).format() } catch (e) { out.tz_date = 'ERR ' + e.message }
  try { out.tz_dayjs = dayjs.tz(newYork, NY).format() } catch (e) { out.tz_dayjs = 'ERR ' + e.message }
  try { out.tz_dayjs_val = dayjs.tz(newYork, NY).valueOf() } catch (e) { out.tz_dayjs_val = 'ERR ' + e.message }
  const la = dayjs('2014-06-01T12:00:00Z').tz('America/Los_Angeles')
  out.la_format = la.format()
  out.la_formatZ = la.format('Z')
  out.la_offset = la.utcOffset()
  // non-zero ms
  const laMs = dayjs('2014-06-01T12:00:00.123Z').tz('America/Los_Angeles')
  out.laMs_format = laMs.format()
  out.laMs_formatZ = laMs.format('Z')
  out.laMs_offset = laMs.utcOffset()
  const nyMs = dayjs('2014-06-01T12:00:00.123Z').tz(NY)
  out.nyMs_format = nyMs.format()
  out.nyMs_formatZ = nyMs.format('Z')
  out.nyMs_offset = nyMs.utcOffset()
  // tz() with no argument
  try { out.tz_noarg = dayjs('2014-06-01T12:00:00Z').tz().format() } catch (e) { out.tz_noarg = 'ERR ' + e.message }
  // d.tz with no timezone
  try { out.dtz_noarg = dayjs.tz('2014-06-01 12:00').format() } catch (e) { out.dtz_noarg = 'ERR ' + e.message }
  console.log('PROBE_RESULT ' + JSON.stringify(out, null, 2))
  expect(true).toBe(true)
})
```

Run it with: `cd /dayjs && TZ=UTC npx jest test/zzz_probe.test.js --coverage=false 2>&1 | head -100`
Also run with `TZ=America/New_York npx jest test/zzz_probe.test.js --coverage=false 2>&1 | head -100` and `TZ=Europe/London ...`.

Then DELETE /dayjs/test/zzz_probe.test.js and confirm `git status --porcelain` is clean.

Report the full PROBE_RESULT JSON for each TZ, verbatim. This is read-only probing of current behavior.

Working dir /dayjs. Apply EXACTLY this one edit to /dayjs/src/plugin/weekYear/index.js and nothing else. Change the `proto.weekYear` function from:
```
  proto.weekYear = function () {
    const month = this.month()
    const weekOfYear = this.week()
    const year = this.year()
    if (weekOfYear === 1 && month === 11) {
      return year + 1
    }
    return year
  }
```
to:
```
  proto.weekYear = function () {
    const month = this.month()
    const weekOfYear = this.week()
    const year = this.year()
    if (weekOfYear === 1 && month === 11) {
      return year + 1
    }
    if (month === 0 && weekOfYear >= 52) {
      return year - 1
    }
    return year
  }
```

Then create the temp file /dayjs/test/zzz_weekyear.test.js with EXACTLY:
```js
import moment from 'moment'
import dayjs from '../src'
import weekYear from '../src/plugin/weekYear'
import weekOfYear from '../src/plugin/weekOfYear'
import '../src/locale/en-gb'

dayjs.extend(weekYear)
dayjs.extend(weekOfYear)

it('yearStart: 4', () => {
  dayjs.locale('en-gb')
  moment.locale('en-gb')
  const cases = ['2021-01-01', '2016-01-01', '2017-01-01', '2022-01-01', '2020-12-31', '2018-12-31', '2019-01-01', '2018-12-30']
  cases.forEach((c) => {
    expect(dayjs(c).weekYear()).toBe(moment(c).weekYear())
  })
  expect(dayjs('2021-01-01').weekYear()).toBe(2020)
  expect(dayjs('2016-01-01').weekYear()).toBe(2015)
  expect(dayjs('2018-12-31').weekYear()).toBe(2019)
})
```

Run:
1. `cd /dayjs && npx jest test/zzz_weekyear.test.js test/plugin/weekYear.test.js test/plugin/weekOfYear.test.js --coverage=false 2>&1 | tail -30`
2. `cd /dayjs && npm test 2>&1 | tail -8`

Then DELETE /dayjs/test/zzz_weekyear.test.js and run `cd /dayjs && git status --porcelain`.

Report: (a) verbatim final content of /dayjs/src/plugin/weekYear/index.js, (b) outputs of commands 1 and 2, (c) git status.

Working dir /dayjs. Apply EXACTLY these edits to /dayjs/src/plugin/customParseFormat/index.js and nothing else.

First run `cd /dayjs && grep -n "matchUpperCaseAMPM\|matchLowerCaseAMPM" src/plugin/customParseFormat/index.js` and report the output (they should only appear in their definitions and in expressions.A / expressions.a).

EDIT 1 — delete these two lines:
```
const matchUpperCaseAMPM = /[AP]M/
const matchLowerCaseAMPM = /[ap]m/
```

EDIT 2 — immediately BEFORE the line `const expressions = {`, insert:
```
const meridiemMatch = (input, isLowerCase) => {
  let isAfternoon
  const { meridiem } = locale
  if (!meridiem) {
    isAfternoon = input === (isLowerCase ? 'pm' : 'PM')
  } else {
    for (let i = 1; i <= 24; i += 1) {
      // todo: fix input === meridiem(i, 0, isLowerCase)
      if (input.indexOf(meridiem(i, 0, isLowerCase)) > -1) {
        isAfternoon = i > 12
        break
      }
    }
  }
  return isAfternoon
}
```

EDIT 3 — replace:
```
  A: [matchUpperCaseAMPM, function (input) {
    this.afternoon = input === 'PM'
  }],
  a: [matchLowerCaseAMPM, function (input) {
    this.afternoon = input === 'pm'
  }],
```
with:
```
  A: [matchWord, function (input) {
    this.afternoon = meridiemMatch(input, false)
  }],
  a: [matchWord, function (input) {
    this.afternoon = meridiemMatch(input, true)
  }],
```

Then create the temp file /dayjs/test/zzz_meridiem.test.js with EXACTLY:
```js
import dayjs from '../src'
import customParseFormat from '../src/plugin/customParseFormat'
import '../src/locale/zh-cn'
import '../src/locale/ja'
import '../src/locale/ko'
import '../src/locale/br'

dayjs.extend(customParseFormat)

it('meridiem locale AM', () => {
  const d = dayjs('2018-05-02 1:02:03 上午', 'YYYY-MM-DD h:mm:ss A', 'zh-cn')
  expect(d.format('YYYY-MM-DD HH:mm:ss')).toBe('2018-05-02 01:02:03')
})

it('meridiem locale PM', () => {
  const d = dayjs('2018-05-02 1:02:03 下午', 'YYYY-MM-DD h:mm:ss A', 'zh-cn')
  expect(d.format('YYYY-MM-DD HH:mm:ss')).toBe('2018-05-02 13:02:03')
})

it('english still works', () => {
  expect(dayjs('2018-05-02 1:02:03 PM', 'YYYY-MM-DD h:mm:ss A').format('HH:mm:ss')).toBe('13:02:03')
  expect(dayjs('2018-05-02 1:02:03 AM', 'YYYY-MM-DD h:mm:ss A').format('HH:mm:ss')).toBe('01:02:03')
  expect(dayjs('2018-05-02 1:02:03 pm', 'YYYY-MM-DD h:mm:ss a').format('HH:mm:ss')).toBe('13:02:03')
  expect(dayjs('2018-05-02 1:02:03 am', 'YYYY-MM-DD h:mm:ss a').format('HH:mm:ss')).toBe('01:02:03')
})

it('other locales info', () => {
  console.log('JA_AM=' + dayjs('2018-05-02 1:02:03 午前', 'YYYY-MM-DD h:mm:ss A', 'ja').format('HH:mm:ss'))
  console.log('JA_PM=' + dayjs('2018-05-02 1:02:03 午後', 'YYYY-MM-DD h:mm:ss A', 'ja').format('HH:mm:ss'))
  console.log('KO_PM=' + dayjs('2018-05-02 1:02:03 오후', 'YYYY-MM-DD h:mm:ss A', 'ko').format('HH:mm:ss'))
  console.log('BR_PM=' + dayjs('2018-05-02 1:02:03 g.m.', 'YYYY-MM-DD h:mm:ss A', 'br').format('HH:mm:ss'))
  console.log('ZHCN_NOON=' + dayjs('2018-05-02 12:02:03 中午', 'YYYY-MM-DD h:mm:ss A', 'zh-cn').format('HH:mm:ss'))
})
```

Run:
1. `cd /dayjs && npx jest test/zzz_meridiem.test.js --coverage=false 2>&1 | tail -40`
2. `cd /dayjs && npx jest test/plugin/customParseFormat.test.js --coverage=false 2>&1 | tail -15`
3. `cd /dayjs && npm test 2>&1 | tail -8`

Then DELETE /dayjs/test/zzz_meridiem.test.js and run `cd /dayjs && git status --porcelain`.

Report: (a) the grep output from the first step, (b) the verbatim final content of the `meridiemMatch` function and the `A`/`a` expressions, (c) outputs of commands 1-3 (including the JA_AM/JA_PM/KO_PM/BR_PM/ZHCN_NOON console lines), (d) git status.
